{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Pentazocine, the closest high-transfer morphinan/benzomorphan opioid analogue, has a mean absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Meptazinol, a phenolic opioid with a basic amine, has absolute oral bioavailability of 8.7 ± 1.6% in normal young male volunteers, well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Pethidine, a phenylpiperidine opioid, has absolute oral bioavailability of 0.48 in healthy volunteers, above the threshold, indicating that not all opioid analgesics have low oral bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ciramadol, a phenolic cyclohexanol opioid, showed 80 ± 7% oral bioavailability in cirrhotic patients, above the threshold, but this was measured in cirrhosis and may overestimate normal first-pass conditions.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C49"],
      "claim": "Paliperidone, a piperidine antipsychotic with 28% absolute oral bioavailability, is above the threshold but lacks the morphinan/phenolic opioid features of the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 4,5-epoxymorphinan opioid with phenolic 3-OH, 6-OH, and 14-OH and an N-cyclobutylmethyl group. The closest analogue pentazocine (F≈18%) and the phenolic opioid meptazinol (F≈9%) both fall below 20%, consistent with extensive first-pass metabolism of such phenolic morphinans. Higher-F analogues are structurally more distant or measured in cirrhosis, so they do not override the low-F evidence. Prediction: low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself was provided.",
    "Pentazocine data include a cirrhotic-patient value of 68% and inter-individual variability (14.6–31.6%), adding uncertainty around the exact threshold.",
    "High-F analogues (pethidine, paliperidone, ciramadol) are structurally less similar or measured under altered physiological conditions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

